insert into public.penteado_passos (penteado_id, numero, titulo, instrucao, vista) select p.id, v.n, v.t, v.i, v.vi from public.penteados p, (values (1,'Divida as mechas','Separe o cabelo em três mechas parecidas (só na mecha da frente).','back'),(2,'Comece a trançar','Cruze a mecha da direita no meio, depois a da esquerda.','back'),(3,'Siga até o fim','Continue alternando até as pontas, sem apertar demais.','side'),(4,'Prenda a ponta','Finalize com um elástico macio.','detail')) v(n,t,i,vi) where p.slug = 'tranca-frontal' on conflict (penteado_id, numero) do nothing;
insert into public.penteados (nome, slug, descricao, familia, tipos, comprimentos, treinos, minutos, dificuldade, fixacao, acessorios, destaque, ordem, status) values ('Twist frontal', 'twist-frontal', 'Torcidinho na frente, rápido e firme.', 'twist', array['crespo','cacheado','ondulado']::text[], array['curto','medio']::text[], array['corrida','yoga','funcional']::text[], 4, 'facil', 'media', array['grampos']::text[], false, 490, 'publicado') on conflict (slug) do nothing;
insert into public.penteado_passos (penteado_id, numero, titulo, instrucao, vista) select p.id, v.n, v.t, v.i, v.vi from public.penteados p, (values (1,'Separe uma mecha','Pegue uma mecha da frente.','front'),(2,'Divida em duas','Divida a mecha em duas partes iguais.','front'),(3,'Torça uma na outra','Enrole uma parte na outra, para trás.','side'),(4,'Prenda a ponta','Finalize com grampo ou mini elástico.','detail')) v(n,t,i,vi) where p.slug = 'twist-frontal' on conflict (penteado_id, numero) do nothing;

select 'Cabelo para Treinar pronto (DESATIVADO para as alunas)' as status, (select count(*) from public.penteados) as penteados;
